CREATE TABLE "__mistri_delivery_receipt" (
  destination_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(destination_id)='text' AND instr(destination_id,char(0))=0 AND length(CAST(destination_id AS BLOB)) BETWEEN 1 AND 128) REFERENCES "__mistri_delivery_destination" (id) ON DELETE RESTRICT,
  receipt_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(receipt_id)='text' AND instr(receipt_id,char(0))=0 AND length(CAST(receipt_id AS BLOB)) BETWEEN 1 AND 128) REFERENCES "__mistri_command_receipt" (id) ON DELETE RESTRICT,
  event_count INTEGER NOT NULL CHECK (typeof(event_count)='integer' AND event_count BETWEEN 0 AND 32),
