CREATE TABLE "__mistri_delivery_delivery" (
  destination_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(destination_id)='text' AND instr(destination_id,char(0))=0 AND length(CAST(destination_id AS BLOB)) BETWEEN 1 AND 128) REFERENCES "__mistri_delivery_destination" (id) ON DELETE RESTRICT,
  event_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(event_id)='text' AND instr(event_id,char(0))=0 AND length(CAST(event_id AS BLOB)) BETWEEN 1 AND 36) REFERENCES "__mistri_event_event" (event_id) ON DELETE RESTRICT,
  receipt_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(receipt_id)='text' AND instr(receipt_id,char(0))=0 AND length(CAST(receipt_id AS BLOB)) BETWEEN 1 AND 128) REFERENCES "__mistri_command_receipt" (id) ON DELETE RESTRICT,
  ordinal INTEGER NOT NULL CHECK (typeof(ordinal)='integer' AND ordinal BETWEEN 0 AND 31),
  state TEXT NOT NULL CHECK (state IN ('pending','leased','retry','unknown','delivered','failed')),
  attempts INTEGER NOT NULL CHECK (typeof(attempts)='integer' AND attempts BETWEEN 0 AND 67),
  redrives INTEGER NOT NULL CHECK (typeof(redrives)='integer' AND redrives BETWEEN 0 AND 3),
  attempt_limit INTEGER NOT NULL CHECK (typeof(attempt_limit)='integer' AND attempt_limit BETWEEN 1 AND 67),
  next_at INTEGER NOT NULL CHECK (typeof(next_at)='integer' AND next_at BETWEEN 0 AND 9007199254740991),
  token TEXT,
  lease_until INTEGER,
  last_code TEXT CHECK (last_code IN ('accepted','rejected','transport','timeout','shutdown','lease_expired','redriven')),
  PRIMARY KEY (destination_id,event_id),
  UNIQUE (destination_id,receipt_id,ordinal),
  CHECK (attempts<=attempt_limit),
  CHECK ((state='leased' AND typeof(token)='text' AND length(token)=36 AND typeof(lease_until)='integer' AND lease_until>=0 AND attempts>0)
    OR (state<>'leased' AND token IS NULL AND lease_until IS NULL)),
  CHECK ((state='pending' AND attempts=0 AND last_code IS NULL) OR (state<>'pending' AND attempts>0))
);
CREATE TABLE "__mistri_delivery_attempt" (
  destination_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(destination_id)='text' AND instr(destination_id,char(0))=0 AND length(CAST(destination_id AS BLOB)) BETWEEN 1 AND 128),
  event_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(event_id)='text' AND instr(event_id,char(0))=0 AND length(CAST(event_id AS BLOB)) BETWEEN 1 AND 36),
  attempt INTEGER NOT NULL CHECK (typeof(attempt)='integer' AND attempt BETWEEN 1 AND 67),
  token TEXT UNIQUE CHECK (token IS NULL OR (typeof(token)='text' AND length(token)=36)),
  started_at INTEGER NOT NULL CHECK (typeof(started_at)='integer' AND started_at BETWEEN 0 AND 9007199254740991),
  deadline INTEGER CHECK (deadline IS NULL OR typeof(deadline)='integer'),
  outcome TEXT NOT NULL CHECK (outcome IN ('leased','accepted','rejected','unknown','redriven')),
  code TEXT CHECK (code IN ('accepted','rejected','transport','timeout','shutdown','lease_expired','redriven')),
  finished_at INTEGER,
  operator TEXT CHECK (operator IS NULL OR (typeof(operator)='text' AND instr(operator,char(0))=0 AND length(CAST(operator AS BLOB)) BETWEEN 1 AND 128)),
  PRIMARY KEY (destination_id,event_id,attempt),
  FOREIGN KEY (destination_id,event_id) REFERENCES "__mistri_delivery_delivery" (destination_id,event_id) ON DELETE RESTRICT,
  CHECK ((outcome='redriven' AND token IS NULL AND deadline IS NULL AND code IS 'redriven' AND typeof(finished_at)='integer'
      AND finished_at=started_at AND operator IS NOT NULL)
    OR (outcome<>'redriven' AND typeof(token)='text' AND typeof(deadline)='integer' AND deadline>started_at AND operator IS NULL
      AND ((outcome='leased' AND code IS NULL AND finished_at IS NULL)
        OR (outcome<>'leased' AND code IS NOT NULL AND code<>'redriven' AND typeof(finished_at)='integer' AND finished_at>=started_at))))
);
